def optimize_seating(M, N, K, L, D, chatting_pairs):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.
    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.
    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Initialize a dictionary to store the number of chatting pairs that can be separated by each aisle
    aisle_count = {}
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            aisle_count[(i, j)] = 0

    # Iterate through each chatting pair and increment the aisle count for each aisle that can separate the pair
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(1, M + 1):
            for j in range(1, N + 1):
                if (x1 < i < x2 or x1 > i > x2) and (y1 < j < y2 or y1 > j > y2):
                    aisle_count[(i, j)] += 1

    # Iterate through each aisle and check if it is one of the K horizontal aisles or L vertical aisles needed
    horizontal_aisles = []
    vertical_aisles = []
    for aisle, count in aisle_count.items():
        i, j = aisle
        if count > 0:
            if i in range(1, M + 1) and j not in [1, N]:
                horizontal_aisles.append(aisle)
            elif i not in [1, M] and j in range(1, N + 1):
                vertical_aisles.append(aisle)

    # Sort the aisles by the number of chatting pairs they can separate, in descending order
    horizontal_aisles.sort(key=lambda x: aisle_count[x], reverse=True)
    vertical_aisles.sort(key=lambda x: aisle_count[x], reverse=True)

    # Select the top K horizontal aisles and L vertical aisles with the most chatting pairs that can be separated
    selected_aisles = horizontal_aisles[:K] + vertical_aisles[:L]

    # Return a string representation of the selected aisles
    return " ".join(str(aisle) for aisle in selected_aisles)

