    # choose the item with the highest importance value per unit price
    item = max(items, key=lambda x: x[1] / x[0])
    # if the item's price is less than or equal to the budget, include it in the solution
    if item[0] <= n:
        return item[1] + max_happiness(n - item[0], m - 1, items)
    # if the item's price is greater than the budget, exclude it from the solution
    else:
        return max_happiness(n, m - 1, items)

