def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each length of the necklace
    max_energies = {1: beads[0]}

    # Loop through the rest of the beads
    for i in range(1, len(beads)):
        # Initialize the maximum energy for this iteration
        max_energy = beads[i]

        # Loop through the possible lengths of the necklace
        for j in range(1, i + 1):
            # Calculate the energy for this length
            energy = beads[i] * beads[(i - j) % len(beads)] * beads[(i - j + 1) % len(beads)]

            # Update the maximum energy if necessary
            if energy > max_energy:
                max_energy = energy

        # Add the maximum energy for this iteration to the dictionary
        max_energies[i + 1] = max_energy

    # Return the maximum energy for the entire necklace
    return max(max_energies.values())

def max_energy(beads):
    # Initialize the dynamic programming table
    dp = [[0] * (len(beads) + 1) for _ in range(len(beads) + 1)]

    # Fill in the base cases
    for i in range(len(beads) + 1):
        dp[i][i] = 0
        dp[i][i + 1] = beads[i % len(beads)]

    # Fill in the dynamic programming table
    for i in range(2, len(beads) + 1):
        for j in range(len(beads)):
            for k in range(len(beads)):
                if i <= j <= k:
                    continue
                dp[i][j] = max(dp[i][j], dp[i - 1][k] * beads[k % len(beads)] * beads[(k + 1) % len(beads)])
                dp[i][j] = max(dp[i][j], dp[i - 1][k] * beads[(k + len(beads) - 1) % len(beads)] * beads[k % len(beads)])

    # Return the maximum energy
    return max(dp[len(beads)])

