def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    where each part is at least x and order of parts does not matter.
    """
    if n < k * x:
        return 0
    if k == 1:
        return 1
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for i in range(1, k + 1):
        for j in range(i * x, n + 1):
            dp[i][j] += dp[i - 1][j - i * x]
    return dp[k][n]

def count_partitions(n: int, k: int, x: int) -> int:
    # Initialize a dictionary to store the results of subproblems
    memo = {}

    # Define a helper function to solve the problem
    def helper(n: int, k: int, x: int) -> int:
        # Base case: If n is less than or equal to 0, there is only one way to partition
        if n <= 0:
            return 1

        # If k is less than or equal to 1, there is only one way to partition
        if k <= 1:
            return 1

        # If the solution to this subproblem has already been computed, return it
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        # Recursive case: Consider all possible values for the first part
        count = 0
        for i in range(x, n):
            count += helper(n - i, k - 1, i)

        # Memoize the result of this subproblem
        memo[(n, k, x)] = count

        return count

    # Call the helper function to solve the problem
    return helper(n, k, x)

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
    return 0
    else:
    return count_partitions(n - x, k, x) + count_partitions(n, k - 1, x)

