    postorder_vals = {i: c for i, c in enumerate(postorder)}
    def dfs(start, end):
        if start > end:
            return ''
        if start == end:
            return inorder_vals[start]
        root = postorder_vals[end]
        root_idx = inorder_idx[root]
        left = dfs(start, root_idx-1)
