def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize the dynamic programming table with -1
    dp = [[-1] * (T + 1) for _ in range(M + 1)]

    # Initialize the base case
    for i in range(M + 1):
        dp[i][0] = 0

    # Fill in the dynamic programming table
    for i in range(1, M + 1):
        for t in range(1, T + 1):
            dp[i][t] = max(dp[i - 1][t], dp[i - 1][t - herbs[i - 1][0]] + herbs[i - 1][1])

    # Return the maximum value
    return dp[M][T]

def min_remaining_space(V, n, volumes):
    # Initialize a dynamic programming table to store the maximum volume that can be occupied
    # by any subset of the given items.
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table with the values from the given capacities.
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            dp[i][j] = max(dp[i - 1][j], volumes[i - 1] + dp[i - 1][j - volumes[i - 1]])

    # Return the difference between the box's total capacity and the maximum occupied volume.
    return V - dp[n][V]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [1] + [0] * m
    for i in range(1, n+1):
        for j in range(m, 0, -1):
            if j >= a[i-1]:
                dp[j] = (dp[j] + dp[j-a[i-1]]) % MOD
    return dp[m]

def calculate_arrangements(n, m, a):
    """
    Compute the number of ways to arrange m pots of flowers using up to n types,
    where the ith type can have at most a[i] pots, and the arrangement must be in
    increasing order of flower types.
    """
    # Initialize a 2D array to store the number of arrangements for each type
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the base cases
    for i in range(n + 1):
        dp[i][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]
            if a[i - 1] >= j:
                dp[i][j] += dp[i][j - 1]

    return dp[n][m] % (10**6 + 7)

def mod_inverse(a, b):
    gcd, x, _ = extended_euclidean_algorithm(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def extended_euclidean_algorithm(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        gcd, x, y = extended_euclidean_algorithm(b, a % b)
        return (gcd, y, x - (a // b) * y)

