from heapq import heappush, heappop

def minimum_cost_to_merge_fruits(fruit_counts):
    min_heap = []
    for fruit, count in enumerate(fruit_counts):
        if count > 0:
            heappush(min_heap, (count, fruit))

    total_cost = 0
    while len(min_heap) > 1:
        heap1 = heappop(min_heap)
        heap2 = heappop(min_heap)
        total_cost += heap1[0] + heap2[0]
        heappush(min_heap, (heap1[0] + heap2[0], heap1[1]))

    return total_cost

