def min_groups(w, n, prices):
    # Initialize a list to store the prices of souvenirs in each group
    groups = []
    # Initialize a variable to keep track of the total price of souvenirs in each group
    total_price = 0
    # Iterate over the list of prices
    for price in prices:
        # If the total price of the current group plus the price of the current souvenir is less than or equal to the maximum allowed sum, add the price to the current group
        if total_price + price <= w:
            total_price += price
        # Otherwise, create a new group and add the price of the current souvenir to it
        else:
            total_price = price
            groups.append([total_price])
    # If there are any remaining souvenirs that have not been added to a group, add them to the last group
    if len(prices) % n != 0:
        groups[-1].extend(prices[len(prices) % n:])
    # Return the length of the list of groups, which represents the minimum number of groups needed to distribute all souvenirs
    return len(groups)

